            if index == 9 && (byte & 128 != 0 || payload > 1) { return Err(PackRefusal::Malformed { kind: ValueRefusalKind::InvalidValue, what: "varint", offset: start as u64, detail: "overlong varint (exceeds 10 bytes / 64 bits)".into() }); }
